try {
  const raw = $input.first().json.output;
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(cleaned);
  return [{json: {topico: parsed.topico || '', post: parsed.post || raw, tema_principal: parsed.tema_principal || 'Outros', noticia_origem: parsed.noticia_origem || '', link_origem: parsed.link_origem || '', formato_usado: parsed.formato_usado || '', gancho_usado: parsed.gancho_usado || '', raw_output: raw}}];
} catch (e) {
  return [{json: {topico: 'Sem topico', post: $input.first().json.output, tema_principal: 'Outros', noticia_origem: '', link_origem: '', formato_usado: '', gancho_usado: '', raw_output: $input.first().json.output, parse_error: e.message}}];
}

// Crie uma chave gratuita na API do Pexels e substitua abaixo.
// NUNCA publique um template com a sua chave real.
const PEXELS_KEY = 'COLOQUE_SUA_CHAVE_PEXELS_AQUI';

if (PEXELS_KEY.includes('COLOQUE_')) {
  return [{ json: {
    imageUrl: null,
    source: 'pexels',
    status: 'configure_a_chave_pexels',
    query: ''
  }}];
}

const helpers = this.helpers;
const tema = ($('Parse JSON Output').first().json.tema_principal || '').toLowerCase();

const mapa = {
  'marketing': 'digital marketing analytics office',
  'seo': 'search engine optimization laptop',
  'google ads': 'digital advertising analytics laptop',
  'meta': 'social media marketing smartphone',
  'linkedin': 'professional networking business',
  'ia': 'artificial intelligence business laptop',
  'inteligencia artificial': 'artificial intelligence business',
  'automacao': 'business automation technology',
  'crm': 'customer relationship management office',
  'vendas': 'sales team business office',
  'ecommerce': 'ecommerce business laptop'
};

let query = 'business technology laptop office';
for (const k of Object.keys(mapa)) {
  if (tema.includes(k)) { query = mapa[k]; break; }
}

try {
  const url = 'https://api.pexels.com/v1/search?query=' + encodeURIComponent(query) +
    '&orientation=landscape&per_page=15&size=large';

  const resp = await helpers.httpRequest({
    method: 'GET',
    url,
    headers: { Authorization: PEXELS_KEY },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 15000
  });

  if (resp.statusCode !== 200 || !resp.body?.photos?.length) {
    return [{ json: {
      imageUrl: null,
      source: 'pexels',
      status: 'sem_resultado_' + resp.statusCode,
      query
    }}];
  }

  const photos = resp.body.photos;
  const photo = photos[Math.floor(Math.random() * photos.length)];
  const imageUrl = photo.src?.large2x || photo.src?.large || photo.src?.original || null;

  return [{ json: {
    imageUrl,
    source: 'pexels: ' + query,
    status: 'ok',
    query,
    photographer: photo.photographer || '',
    pexels_url: photo.url || ''
  }}];
} catch (e) {
  return [{ json: {
    imageUrl: null,
    source: 'pexels',
    status: 'erro',
    error: (e.message || '').slice(0, 200),
    query
  }}];
}

