// ===== TOKEN DO LINKEDIN (trocar a cada ~60 dias) =====
const token = 'COLOQUE_SEU_TOKEN_LINKEDIN_AQUI';
if (token.includes('COLOQUE_')) return [{json:{error:'configure_o_token_linkedin'}}];
// ==============================================================
const helpers = this.helpers;
const inputItem = $input.first();
const hasBinary = inputItem.binary && inputItem.binary.data;

const userInfo = await helpers.httpRequest({method:'GET',url:'https://api.linkedin.com/v2/userinfo',headers:{Authorization:'Bearer '+token},json:true,returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:15000});
const authorUrn = userInfo.statusCode === 200 ? 'urn:li:person:' + userInfo.body.sub : null;
if (!authorUrn) return [{json:{error:'no_urn', userInfoStatus:userInfo.statusCode, token}, binary: inputItem.binary}];
if (!hasBinary) return [{json:{authorUrn, hasBinary:false, token}, binary: inputItem.binary}];

const reg = await helpers.httpRequest({
  method:'POST',
  url:'https://api.linkedin.com/v2/assets?action=registerUpload',
  headers:{Authorization:'Bearer '+token,'Content-Type':'application/json','X-Restli-Protocol-Version':'2.0.0'},
  body:{registerUploadRequest:{recipes:['urn:li:digitalmediaRecipe:feedshare-image'],owner:authorUrn,serviceRelationships:[{relationshipType:'OWNER',identifier:'urn:li:userGeneratedContent'}],supportedUploadMechanism:['SYNCHRONOUS_UPLOAD']}},
  json:true,returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:15000
});

if (reg.statusCode !== 200 || !reg.body || !reg.body.value) {
  return [{json:{authorUrn, error:'register_failed', registerStatus:reg.statusCode, token}, binary: inputItem.binary}];
}

const mech = reg.body.value.uploadMechanism['com.linkedin.digitalmedia.uploading.MediaUploadHttpRequest'];

return [{
  json: {authorUrn, uploadUrl: mech.uploadUrl, asset: reg.body.value.asset, token},
  binary: inputItem.binary
}];

// ===== TOKEN DO LINKEDIN =====
const token = 'COLOQUE_SEU_TOKEN_LINKEDIN_AQUI';
if (token.includes('COLOQUE_')) return [{json:{error:'configure_o_token_linkedin'}}];
// ======================================
const helpers = this.helpers;

const uploadResp = $input.first().json;
const uploadStatus = uploadResp.statusCode;
const registerData = $('Register LinkedIn Asset Profile').first().json;
const postText = $('Parse JSON Output').first().json.post;

const authorUrn = registerData.authorUrn;
const assetUrn = (uploadStatus === 201 || uploadStatus === 200) ? registerData.asset : null;

if (assetUrn) await new Promise(r=>setTimeout(r,2000));

const body = assetUrn
  ? {author:authorUrn,lifecycleState:'PUBLISHED',specificContent:{'com.linkedin.ugc.ShareContent':{shareCommentary:{text:postText},shareMediaCategory:'IMAGE',media:[{status:'READY',description:{text:''},media:assetUrn,title:{text:''}}]}},visibility:{'com.linkedin.ugc.MemberNetworkVisibility':'PUBLIC'}}
  : {author:authorUrn,lifecycleState:'PUBLISHED',specificContent:{'com.linkedin.ugc.ShareContent':{shareCommentary:{text:postText},shareMediaCategory:'NONE'}},visibility:{'com.linkedin.ugc.MemberNetworkVisibility':'PUBLIC'}};

const response = await helpers.httpRequest({
  method:'POST',
  url:'https://api.linkedin.com/v2/ugcPosts',
  headers:{Authorization:'Bearer '+token,'Content-Type':'application/json','X-Restli-Protocol-Version':'2.0.0'},
  body:body,
  json:true,returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:15000
});

return [{json:{
  destino: 'PERFIL',
  postedWithImage: !!assetUrn,
  uploadStatus,
  status: response.statusCode,
  success: response.statusCode === 201 || response.statusCode === 200,
  postId: (response.headers && response.headers['x-restli-id']) || null,
  erro: (response.statusCode >= 300) ? JSON.stringify(response.body).slice(0,300) : null,
  assetUrn
}}];
